package forth

import (
	"errors"
	"fmt"
	"strconv"
	"strings"
)

// Forth implements a very simple subset of Forth.
//
// It supports integer arithmetic (+, -, *, /), stack manipulation
// (DUP, DROP, SWAP, OVER) and the definition of new words using the
// customary syntax `: word-name definition ;`.
//
// Words are case-insensitive. A number is a sequence of one or more
// ASCII digits, optionally preceded by a minus sign; anything else is
// a word.
func Forth(input []string) ([]int, error) {
	f := &forth{
		stack: []int{},
		defs:  map[string][]string{},
	}
	for _, line := range input {
		if err := f.evaluate(strings.Fields(line)); err != nil {
			return nil, err
		}
	}
	return f.stack, nil
}

type forth struct {
	stack []int
	defs  map[string][]string

	// State for a `: ... ;` definition that may span multiple lines.
	defining bool
	defName  string
	defBody  []string
}

var (
	errEmptyStack   = errors.New("empty stack")
	errOneOnStack   = errors.New("only one value on the stack")
	errDivideByZero = errors.New("division by zero")
	errIllegal      = errors.New("illegal operation")
)

// evaluate executes a sequence of tokens.
func (f *forth) evaluate(words []string) error {
	for i := 0; i < len(words); i++ {
		word := words[i]
		lw := strings.ToLower(word)

		if f.defining {
			if lw == ";" {
				f.defs[f.defName] = f.defBody
				f.defining = false
				f.defName = ""
				f.defBody = nil
			} else {
				f.defBody = append(f.defBody, f.resolve(word)...)
			}
			continue
		}

		if lw == ":" {
			i++
			if i >= len(words) {
				return errors.New("missing word name")
			}
			name := strings.ToLower(words[i])
			if isNumber(name) {
				return errIllegal
			}
			f.defining = true
			f.defName = name
			f.defBody = nil
			continue
		}

		if err := f.evalWord(word); err != nil {
			return err
		}
	}
	return nil
}

// evalWord executes a single token that is not part of a definition.
func (f *forth) evalWord(word string) error {
	lw := strings.ToLower(word)
	if def, ok := f.defs[lw]; ok {
		return f.evaluate(def)
	}
	switch lw {
	case "+":
		return f.add()
	case "-":
		return f.sub()
	case "*":
		return f.mul()
	case "/":
		return f.div()
	case "dup":
		return f.dup()
	case "drop":
		return f.drop()
	case "swap":
		return f.swap()
	case "over":
		return f.over()
	}
	if n, err := strconv.Atoi(word); err == nil {
		f.push(n)
		return nil
	}
	return fmt.Errorf("undefined operation: %s", word)
}

// resolve expands a definition-body token. User-defined words are
// inlined (replaced by their current definition) so that a word
// captures the definitions in effect when it was defined; built-in
// words and numbers are kept as-is and evaluated at call time.
func (f *forth) resolve(word string) []string {
	if def, ok := f.defs[strings.ToLower(word)]; ok {
		return def
	}
	return []string{word}
}

func isNumber(word string) bool {
	_, err := strconv.Atoi(word)
	return err == nil
}

// Stack operations.

func (f *forth) push(v int) {
	f.stack = append(f.stack, v)
}

// pop2 pops the top two values, returning them in stack order
// (second-from-top first).
func (f *forth) pop2() (int, int, error) {
	n := len(f.stack)
	if n == 0 {
		return 0, 0, errEmptyStack
	}
	if n == 1 {
		return 0, 0, errOneOnStack
	}
	a := f.stack[n-2]
	b := f.stack[n-1]
	f.stack = f.stack[:n-2]
	return a, b, nil
}

func (f *forth) add() error {
	a, b, err := f.pop2()
	if err != nil {
		return err
	}
	f.push(a + b)
	return nil
}

func (f *forth) sub() error {
	a, b, err := f.pop2()
	if err != nil {
		return err
	}
	f.push(a - b)
	return nil
}

func (f *forth) mul() error {
	a, b, err := f.pop2()
	if err != nil {
		return err
	}
	f.push(a * b)
	return nil
}

func (f *forth) div() error {
	a, b, err := f.pop2()
	if err != nil {
		return err
	}
	if b == 0 {
		return errDivideByZero
	}
	f.push(a / b)
	return nil
}

func (f *forth) dup() error {
	if len(f.stack) == 0 {
		return errEmptyStack
	}
	f.push(f.stack[len(f.stack)-1])
	return nil
}

func (f *forth) drop() error {
	if len(f.stack) == 0 {
		return errEmptyStack
	}
	f.stack = f.stack[:len(f.stack)-1]
	return nil
}

func (f *forth) swap() error {
	if len(f.stack) < 2 {
		if len(f.stack) == 0 {
			return errEmptyStack
		}
		return errOneOnStack
	}
	n := len(f.stack)
	f.stack[n-2], f.stack[n-1] = f.stack[n-1], f.stack[n-2]
	return nil
}

func (f *forth) over() error {
	if len(f.stack) < 2 {
		if len(f.stack) == 0 {
			return errEmptyStack
		}
		return errOneOnStack
	}
	f.push(f.stack[len(f.stack)-2])
	return nil
}
